import sys

def main():
    line = sys.stdin.readline()
    if not line:
        return
    n = int(line.strip())

    if n % 2 == 1:
        print("First")
        sys.stdout.flush()
        pairs = [0] * (2 * n + 1)
        for i in range(1, 2 * n + 1):
            pairs[i] = ((i - 1) // 2) + 1
        print(*(pairs[1:]))
        sys.stdout.flush()
    else:
        print("Second")
        sys.stdout.flush()

        p_line = sys.stdin.readline()
        if not p_line:
            return
        p = list(map(int, p_line.split()))

        groups = {}
        for i, pair_id in enumerate(p):
            num = i + 1
            if pair_id not in groups:
                groups[pair_id] = []
            groups[pair_id].append(num)

        chosen = []
        current_sum = 0
        target_mod = 2 * n

        for pair_id in range(1, n + 1):
            nums = groups[pair_id]
            a, b = nums[0], nums[1]

            rem_a = a % target_mod
            rem_b = b % target_mod

            if (current_sum + rem_a) % target_mod == 0 or (current_sum + rem_b) % target_mod == 0:
                pass
            else:
                if (current_sum + rem_a) % target_mod < (current_sum + rem_b) % target_mod:
                    chosen.append(a)
                    current_sum += a
                else:
                    chosen.append(b)
                    current_sum += b
                continue

            if (current_sum + rem_a) % target_mod == 1:
                chosen.append(a)
                current_sum += a
            elif (current_sum + rem_b) % target_mod == 1:
                chosen.append(b)
                current_sum += b
            elif (current_sum + rem_a) % target_mod == 0:
                chosen.append(a)
                current_sum += a
            else:
                chosen.append(b)
                current_sum += b

        print(*(chosen))
        sys.stdout.flush()

    result = sys.stdin.readline()
    if result:
        res_val = int(result.strip())

if __name__ == "__main__":
    main()
